export function snowflakeColumn(opts) {
    return { kind: "cloud", name: opts.name, cloud: { snowflake: { columnName: opts.column, type: opts.type } }, ...(opts.tags !== undefined ? { tags: opts.tags } : {}) };
}
export function bigQueryColumn(opts) {
    return { kind: "cloud", name: opts.name, cloud: { bigQuery: { columnName: opts.column, type: opts.type } }, ...(opts.tags !== undefined ? { tags: opts.tags } : {}) };
}
export function calculationColumn(opts) {
    return { kind: "calculation", name: opts.name, expression: opts.expression, ...(opts.tags !== undefined ? { tags: opts.tags } : {}) };
}
export function sourceColumn(opts) {
    return {
        kind: "reference",
        name: opts.name,
        source: opts.source,
        ...(opts.aggregation !== undefined ? { aggregation: opts.aggregation } : {}),
        ...(opts.expanded !== undefined ? { expanded: opts.expanded } : {}),
        ...(opts.tags !== undefined ? { tags: opts.tags } : {}),
    };
}
/** Serialize one public column factory result to the platform wire shape. */
export function serializeTableField(def) {
    switch (def.kind) {
        case "cloud":
            return { cloud: { name: def.name, ...(def.tags !== undefined ? { tags: def.tags } : {}), ...("snowflake" in def.cloud ? { snowflake: def.cloud.snowflake } : { bigQuery: def.cloud.bigQuery }) } };
        case "calculation":
            return { calculation: { name: def.name, text: def.expression, ...(def.tags !== undefined ? { tags: def.tags } : {}) } };
        case "reference":
            return { reference: { name: def.name, field: def.source, ...(def.aggregation !== undefined ? { aggregation: def.aggregation } : {}), ...(def.expanded !== undefined ? { expanded: def.expanded } : {}), ...(def.tags !== undefined ? { tags: def.tags } : {}) } };
    }
}
